-- Check distinct values for botdetreg in robot_details vs recreg in robot_record
SELECT COUNT(DISTINCT rd.botdetreg), COUNT(DISTINCT rr.recreg) 
FROM robot_details rd, robot_record rr;

-- Check distinct robot_ids in each CTE source
SELECT COUNT(DISTINCT operbotdetref) FROM operation;
SELECT COUNT(DISTINCT effectivenessrobot) FROM performance_and_safety;

SELECT COUNT(DISTINCT mfgnameval) FROM robot_details;
SELECT COUNT(DISTINCT modelseriesval) FROM robot_details;
SELECT COUNT(DISTINCT bottypeval) FROM robot_details;

-- Maybe the task wants us to join with robot_details and use botdetreg as the robot identifier
-- Check how many robots have operations
SELECT COUNT(DISTINCT operbotdetref) FROM operation;
-- And how many have performance_and_safety entries
SELECT COUNT(DISTINCT effectivenessrobot) FROM performance_and_safety;

-- Check all columns in robot_record and robot_details more carefully
SELECT * FROM robot_record LIMIT 1;
SELECT * FROM robot_details LIMIT 1;

-- Check if there's a 1-to-1 relationship between robot_details and operation/performance_and_safety
SELECT COUNT(*) FROM operation;
SELECT COUNT(DISTINCT operbotdetref) FROM operation;

-- Check if botcode has exactly 100 distinct values when considering some grouping
SELECT COUNT(DISTINCT botcode) FROM robot_record;
-- Check if there are exactly 100 unique modelseriesval
SELECT COUNT(DISTINCT modelseriesval) FROM robot_details;

-- Check if there are exactly 100 robots that have entries in both operation and performance_and_safety
SELECT COUNT(*) FROM (
    SELECT DISTINCT op.operbotdetref 
    FROM operation op
    INNER JOIN performance_and_safety ps ON op.operbotdetref = ps.effectivenessrobot
) sub;
